<?php
require $_SERVER['DOCUMENT_ROOT'].'/main.inc.php';
require_once __DIR__.'/../lib/main.lib.php';
require_once __DIR__.'/../class/InternalTaskService.class.php';
cpo_task_require($db,$user);
$langs->load('chinaplanetoperations@chinaplanetoperations');
$service=new InternalTaskService($db,$user);
$auth=$service->authorization();
$view=$auth->normalizeView(GETPOST('view','alphanohtml'));
$filters=array('view'=>$view,'q'=>GETPOST('q','alphanohtml'),'status'=>GETPOST('status','alphanohtml'),'priority'=>GETPOST('priority','alphanohtml'),'due'=>GETPOST('due','alphanohtml'),'team_id'=>GETPOSTINT('team_id'),'assignee_id'=>GETPOSTINT('assignee_id'),'operation_id'=>GETPOSTINT('operation_id'));
$loadError=false;try{$tasks=$service->listTasks($filters);}catch(Throwable $e){$loadError=true;setEventMessages($langs->trans('InternalTaskSafeError'),null,'errors');$tasks=array();}
$views=$auth->availableViews();$columns=InternalTaskService::boardStatuses();if($view==='archive')$columns['cancelled']=0;$teams=$service->teamOptions(!$auth->isAdministrator());
$selectedTeam=(int)$filters['team_id'];if($selectedTeam<=0&&count($teams)===1)$selectedTeam=(int)$teams[0]['rowid'];
$assignees=$selectedTeam>0?$service->userOptionsForTeam($selectedTeam):array();
$canCreate=($auth->isAdministrator()||$auth->hasRight('task_manage_team'))&&$view!=='my'&&$view!=='archive'&&$view!=='unclassified'&&$selectedTeam>0;
$adminUsers=$auth->isAdministrator()&&$view==='all'?$service->internalUsers():array();
$morecss=array(cpo_asset('/custom/chinaplanetoperations/css/operations.css'));
$morejs=array(cpo_asset('/custom/chinaplanetoperations/js/internal_tasks.js'));
llxHeader('',$langs->trans('InternalTaskBoard'),'','',0,0,$morejs,$morecss);
?>
<main class="cpo-page cpo-task-page" data-direction="<?php echo $langs->trans('DIRECTION')==='rtl'?'rtl':'ltr'; ?>">
<section class="cpo-hero"><div><span class="cpo-eyebrow"><?php echo $langs->trans('InternalTaskEyebrow'); ?></span><h1><?php echo $langs->trans('InternalTaskBoard'); ?></h1><p><?php echo $langs->trans('TaskBoardHelp'); ?></p></div><?php if($auth->isAdministrator()){ ?><a class="button" href="team_admin.php"><?php echo $langs->trans('InternalTaskTeamGrants'); ?></a><?php } ?></section>
<nav class="cpo-task-tabs" aria-label="<?php echo $langs->trans('InternalTaskViews'); ?>"><?php foreach($views as $item)if($item!=='grants'){ ?><a href="?view=<?php echo urlencode($item); ?>"<?php echo $item===$view?' aria-current="page" class="is-active"':''; ?>><?php echo $langs->trans('InternalTaskView_'.$item); ?></a><?php } ?></nav>
<?php if($adminUsers){ ?><form class="cpo-admin-assignee-filter" method="get"><input type="hidden" name="view" value="all"><label class="cpo-field"><span><?php echo $langs->trans('Owner'); ?></span><select name="assignee_id"><option value="0"><?php echo $langs->trans('All'); ?></option><?php foreach($adminUsers as $person){ ?><option value="<?php echo (int)$person['rowid']; ?>"<?php echo (int)$filters['assignee_id']===(int)$person['rowid']?' selected':''; ?>><?php echo dol_escape_htmltag(trim($person['firstname'].' '.$person['lastname'])?:$person['login']); ?></option><?php } ?></select></label><button class="button"><?php echo $langs->trans('Filter'); ?></button></form><?php } ?>
<section class="cpo-panel cpo-task-toolbar"><form method="get"><input type="hidden" name="view" value="<?php echo dol_escape_htmltag($view); ?>"><div class="cpo-filters"><label class="cpo-field"><span><?php echo $langs->trans('Search'); ?></span><input name="q" value="<?php echo dol_escape_htmltag($filters['q']); ?>" placeholder="<?php echo $langs->trans('InternalTaskSearchPlaceholder'); ?>"></label><label class="cpo-field"><span><?php echo $langs->trans('Status'); ?></span><select name="status"><option value=""><?php echo $langs->trans('All'); ?></option><?php foreach(InternalTaskService::allStatuses() as $status)if($status!=='deleted'){ ?><option value="<?php echo $status; ?>"<?php echo $filters['status']===$status?' selected':''; ?>><?php echo $langs->trans('TaskStatus_'.$status); ?></option><?php } ?></select></label><label class="cpo-field"><span><?php echo $langs->trans('Priority'); ?></span><select name="priority"><option value=""><?php echo $langs->trans('All'); ?></option><?php foreach(InternalTaskService::priorities() as $priority){ ?><option value="<?php echo $priority; ?>"<?php echo $filters['priority']===$priority?' selected':''; ?>><?php echo $langs->trans('InternalTaskPriority_'.$priority); ?></option><?php } ?></select></label><label class="cpo-field"><span><?php echo $langs->trans('Deadline'); ?></span><select name="due"><option value=""><?php echo $langs->trans('All'); ?></option><option value="overdue"<?php echo $filters['due']==='overdue'?' selected':''; ?>><?php echo $langs->trans('Overdue'); ?></option><option value="today"<?php echo $filters['due']==='today'?' selected':''; ?>><?php echo $langs->trans('Today'); ?></option><option value="none"<?php echo $filters['due']==='none'?' selected':''; ?>><?php echo $langs->trans('InternalTaskNoDeadline'); ?></option></select></label><?php if($view!=='my'&&$view!=='archive'&&$teams){ ?><label class="cpo-field"><span><?php echo $langs->trans('InternalTaskTeam'); ?></span><select name="team_id"><option value=""><?php echo $langs->trans('All'); ?></option><?php foreach($teams as $team){ ?><option value="<?php echo (int)$team['rowid']; ?>"<?php echo $selectedTeam===(int)$team['rowid']?' selected':''; ?>><bdi><?php echo dol_escape_htmltag($team['nom']); ?></bdi></option><?php } ?></select></label><?php } ?><div class="cpo-form-actions"><button class="button"><?php echo $langs->trans('Search'); ?></button><a class="button" href="?view=<?php echo urlencode($view); ?>"><?php echo $langs->trans('Reset'); ?></a></div></div></form></section>
<?php if($canCreate){ ?><details class="cpo-panel cpo-task-create"><summary><?php echo $langs->trans('AddTask'); ?></summary><form method="post" action="action.php"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="action" value="create"><input type="hidden" name="return_view" value="<?php echo dol_escape_htmltag($view); ?>"><input type="hidden" name="fk_usergroup" value="<?php echo $selectedTeam; ?>"><div class="cpo-context-grid"><label class="cpo-field"><span><?php echo $langs->trans('Task'); ?></span><input required maxlength="255" name="title"></label><label class="cpo-field"><span><?php echo $langs->trans('Owner'); ?></span><select name="fk_user_assign"><option value="0"><?php echo $langs->trans('Unassigned'); ?></option><?php foreach($assignees as $person){ ?><option value="<?php echo (int)$person['rowid']; ?>"><?php echo dol_escape_htmltag(trim($person['firstname'].' '.$person['lastname'])?:$person['login']); ?></option><?php } ?></select></label><label class="cpo-field"><span><?php echo $langs->trans('Priority'); ?></span><select name="priority"><?php foreach(InternalTaskService::priorities() as $priority){ ?><option value="<?php echo $priority; ?>"><?php echo $langs->trans('InternalTaskPriority_'.$priority); ?></option><?php } ?></select></label><label class="cpo-field"><span><?php echo $langs->trans('Deadline'); ?></span><input type="datetime-local" name="date_deadline"></label></div><label class="cpo-field"><span><?php echo $langs->trans('Description'); ?></span><textarea required maxlength="20000" name="description"></textarea></label><button class="button button-save"><?php echo $langs->trans('AddTask'); ?></button></form></details><?php } ?>
<?php if($loadError){ ?><section class="cpo-panel cpo-task-error" role="alert"><h2><?php echo $langs->trans('InternalTaskSafeError'); ?></h2><a class="button" href="<?php echo dol_escape_htmltag($_SERVER['REQUEST_URI']); ?>"><?php echo $langs->trans('Retry'); ?></a></section><?php }elseif(!$tasks){ ?><section class="cpo-panel cpo-task-empty"><span class="fas fa-clipboard-check" aria-hidden="true"></span><h2><?php echo $langs->trans('InternalTaskEmpty_'.$view); ?></h2><p><?php echo $langs->trans('InternalTaskEmptyHelp_'.$view); ?></p></section><?php }else{ ?>
<div class="cpo-stage-nav" aria-live="polite" data-stage-template="<?php echo dol_escape_htmltag($langs->trans('InternalTaskStagePosition')); ?>"><button type="button" data-stage-prev aria-label="<?php echo $langs->trans('Previous'); ?>"></button><strong data-stage-label></strong><button type="button" data-stage-next aria-label="<?php echo $langs->trans('Next'); ?>"></button></div>
<section class="cpo-kanban cpo-task-kanban" aria-label="<?php echo $langs->trans('InternalTaskBoard'); ?>"><?php foreach($columns as $status=>$fixed){$stageTasks=array_values(array_filter($tasks,function($task)use($status){return $task['status']===$status;})); ?><section class="cpo-kanban-column" data-stage="<?php echo $status; ?>" data-stage-name="<?php echo dol_escape_htmltag($langs->trans('TaskStatus_'.$status)); ?>"><header><strong><?php echo $langs->trans('TaskStatus_'.$status); ?></strong><span><?php echo count($stageTasks); ?></span></header><div class="cpo-task-list" role="list"><?php foreach($stageTasks as $task){$overdue=!empty($task['date_deadline'])&&strtotime($task['date_deadline'])<time()&&!in_array($task['status'],array('done','cancelled'),true); ?><article class="cpo-task-card priority-<?php echo dol_escape_htmltag($task['priority']); ?>" role="listitem"><?php if(!empty($task['cover_asset_id'])){ ?><img loading="lazy" src="asset.php?action=preview&amp;asset_id=<?php echo (int)$task['cover_asset_id']; ?>" alt=""><?php } ?><small><bdi><?php echo dol_escape_htmltag($task['ref']); ?></bdi></small><h3><a href="card.php?id=<?php echo (int)$task['rowid']; ?>"><bdi dir="auto"><?php echo dol_escape_htmltag($task['title']); ?></bdi></a></h3><div class="cpo-task-badges"><span class="priority-<?php echo dol_escape_htmltag($task['priority']); ?>"><?php echo $langs->trans('InternalTaskPriority_'.$task['priority']); ?></span><?php if($overdue){ ?><span class="is-overdue"><span class="fas fa-triangle-exclamation" aria-hidden="true"></span><?php echo $langs->trans('Overdue'); ?></span><?php } ?><?php if($task['status']==='waiting'){ ?><span><span class="fas fa-hourglass-half" aria-hidden="true"></span><?php echo $langs->trans('InternalTaskWaitingOn_'.$task['waiting_on']); ?></span><?php } ?></div><progress max="100" value="<?php echo (int)$task['progress']; ?>" aria-label="<?php echo $langs->trans('Progress'); ?>"></progress><footer><span><?php echo dol_escape_htmltag($task['date_deadline']?dol_print_date($db->jdate($task['date_deadline']),'dayhour'):$langs->trans('InternalTaskNoDeadline')); ?></span><?php if($view!=='my'){ ?><span><bdi><?php echo dol_escape_htmltag(trim($task['owner_firstname'].' '.$task['owner_lastname'])?:($task['owner_login']?:$langs->trans('Unassigned'))); ?></bdi></span><?php } ?><span><span class="fas fa-paperclip" aria-hidden="true"></span><?php echo (int)$task['asset_count']; ?></span></footer></article><?php } ?></div></section><?php } ?></section>
<?php } ?></main><dialog class="cpo-task-drawer" data-task-drawer aria-labelledby="cpo-task-drawer-title"><header><strong id="cpo-task-drawer-title"><?php echo $langs->trans('InternalTaskDetails'); ?></strong><button type="button" data-task-drawer-close aria-label="<?php echo $langs->trans('Close'); ?>">×</button></header><iframe title="<?php echo $langs->trans('InternalTaskDetails'); ?>"></iframe></dialog><?php llxFooter();$db->close(); ?>
